import{_ as a,o as i,c as o,a2 as l}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"8.5 电动机的维护与常见故障","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/8-5-dian-dong-ji-de-wei-hu-yu-chang-jian-gu-zhang.md","filePath":"electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/8-5-dian-dong-ji-de-wei-hu-yu-chang-jian-gu-zhang.md","lastUpdated":1793095197000}'),n={name:"electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/8-5-dian-dong-ji-de-wei-hu-yu-chang-jian-gu-zhang.md"};function r(e,t,s,d,g,h){return i(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="_8-5-电动机的维护与常见故障" tabindex="-1">8.5 电动机的维护与常见故障 <a class="header-anchor" href="#_8-5-电动机的维护与常见故障" aria-label="Permalink to &quot;8.5 电动机的维护与常见故障&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>电机也会&quot;生病&quot;。这一节讲日常怎么保养,以及最常见的故障现象和原因判断——很多判断题就是&quot;现象+原因&quot;的连线题。</p><h2 id="一、日常维护要点" tabindex="-1">一、日常维护要点 <a class="header-anchor" href="#一、日常维护要点" aria-label="Permalink to &quot;一、日常维护要点&quot;">​</a></h2><ol><li><strong>清洁</strong>:定期清除电机表面灰尘、油污,保持通风散热良好;</li><li><strong>轴承润滑</strong>:定期检查轴承,补加润滑脂,轴承异常要更换;</li><li><strong>绝缘检查</strong>:定期用<strong>兆欧表</strong>测绕组绝缘电阻(停电后进行),绝缘下降要处理;</li><li><strong>外壳接地</strong>:检查保护接地是否可靠、接线是否牢固;</li><li><strong>运行监视</strong>:听声音、测温度、看电流,发现异常及时处理;</li><li><strong>环境</strong>:防潮、防水、防尘,电机房(罩)保持通风。</li></ol><h2 id="二、常见故障现象与原因-重点" tabindex="-1">二、常见故障现象与原因(重点) <a class="header-anchor" href="#二、常见故障现象与原因-重点" aria-label="Permalink to &quot;二、常见故障现象与原因(重点)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>故障现象</th><th>常见原因</th></tr></thead><tbody><tr><td><strong>不能启动</strong></td><td>电源缺相、绕组断路、控制电路故障、负载卡死、电压过低</td></tr><tr><td><strong>转速变慢/转无力</strong></td><td>电压过低、过载、缺相、轴承卡阻</td></tr><tr><td><strong>过热(烫手)</strong></td><td>过载、通风不良、电压过高/过低、绕组短路或接地</td></tr><tr><td><strong>异响/振动</strong></td><td>轴承损坏、转子不平衡、联轴器不正、缺相</td></tr><tr><td><strong>烧焦味</strong></td><td>绕组过热烧毁(绝缘烧损)</td></tr></tbody></table><blockquote><p>⚠️ <strong>缺相运行是电机的大敌</strong>:三相电源缺了一相,电动机仍可能&quot;带病转&quot;(但电流大增、发热严重),很快烧毁。所以三相电动机应有<strong>缺相保护</strong>,热继电器(三相型)带断相保护功能。</p></blockquote><h2 id="三、故障判断的顺序思路" tabindex="-1">三、故障判断的顺序思路 <a class="header-anchor" href="#三、故障判断的顺序思路" aria-label="Permalink to &quot;三、故障判断的顺序思路&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先查电源(是否缺相/电压) → 再查机械(轴承/负载) → 后查绕组(绝缘/短路)</span></span></code></pre></div><ul><li><strong>先外后内、先机械后电气</strong>,一步步排查;</li><li>需要拆机、测绕组时,必须先<strong>断电、验电、放电</strong>。</li></ul><h2 id="四、检修安全要点" tabindex="-1">四、检修安全要点 <a class="header-anchor" href="#四、检修安全要点" aria-label="Permalink to &quot;四、检修安全要点&quot;">​</a></h2><ul><li>检修前<strong>断开电源并验电</strong>;</li><li>拆开接线盒前确认无电、并放电;</li><li>电动机绕组测量用兆欧表(500 V),测量前断电;</li><li>修好后<strong>空载试转</strong>,检查转向、声音、电流正常再带负载。</li></ul><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 电动机缺相运行会<strong>过热烧毁</strong>,要有缺相保护。</li><li>✅ 定期测绝缘电阻(兆欧表)、检查轴承、检查接地。</li><li>✅ 故障排查:&quot;先电源、后机械、再绕组&quot;。</li><li>⚠️ 易混点:过热的原因可能是过载、电压异常、缺相、通风不良等多种,判断要全面。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>维护四件事:清洁、轴承、绝缘、接地。</li><li>常见故障:不能启动、过热、异响、烧毁,原因要多角度排查。</li><li>缺相运行最伤电机,必须防。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(判断)三相异步电动机缺相运行,会导致电流增大、电动机过热烧毁。( )</li><li>(单选)电动机绕组绝缘电阻应定期用()测量。 A. 万用表　B. 兆欧表　C. 钳形表　D. 电能表</li><li>(判断)电动机外壳保护接地应定期检查。( )</li><li>(单选)电动机通电后不转且发出&quot;嗡嗡&quot;声,最可能的原因是()。 A. 缺相　B. 电压过高　C. 轴承润滑太好　D. 负载太轻</li><li>(判断)检修电动机前,应断开电源并验电。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。缺相运行电流大增、发热,易烧毁。</li><li><strong>B</strong>。绝缘电阻用兆欧表测。</li><li><strong>√</strong>。接地是安全要求,要定期检查。</li><li><strong>A</strong>。缺相时电机通电但不转,常发出&quot;嗡嗡&quot;声。</li><li><strong>√</strong>。断电、验电是检修的前提。</li></ol></details>',20)])])}const b=a(n,[["render",r]]);export{c as __pageData,b as default};
